# frozen_string_literal: true

# Produces nextjs/src/worker/jobs/__fixtures__/generate-community-chat-recap-job.golden.json: GenerateCommunityChatRecapJob run by the
# real app against a scratch database as a Sidekiq job (support/sidekiq_executor.rb), and its sidekiq_retries_exhausted block
# (FailureHandler). The recap is generated by CommunityChatRecapGeneratorService (a model API call), which a marker exception stands
# in for (`reaches_generator`). The block fails the recap and lets its run finish; the finished run triggers the weekly run and the
# notifications through unique-locked jobs, so these cases are replayed against a Redis. Run it like flush-delivered-email-infos-job.rb.
require_relative "support/rails_cases"
include RailsCases

OUT = Rails.root.join("nextjs/src/worker/jobs/__fixtures__/generate-community-chat-recap-job.golden.json")
NOW = Time.utc(2026, 11, 4, 12, 30, 45, 123_000)
SEEDED_AT = "2026-01-01 00:00:00"
TABLES = %w[community_chat_recap_runs community_chat_recaps].freeze

Rails.logger = ActiveSupport::Logger.new(nil)

class HandBackMarker < Exception; end # rubocop:disable Lint/InheritException

CommunityChatRecapGeneratorService.prepend(Module.new do
  def process = raise(HandBackMarker)
end)

# 2026-11-07 is a Saturday: a finished daily run for it triggers the weekly run.
def run_row(id, from: "2026-11-03 00:00:00", frequency: "daily", **overrides)
  { id:, recap_frequency: frequency, from_date: from, to_date: from.sub("00:00:00", "23:59:59"), recaps_count: 2, finished_at: nil, notified_at: nil, created_at: SEEDED_AT, updated_at: SEEDED_AT }.merge(overrides)
end

def recap_row(id, run: 1, status: "pending", **overrides)
  { id:, community_chat_recap_run_id: run, status:, created_at: SEEDED_AT, updated_at: SEEDED_AT }.merge(overrides)
end

def run(name, args, runs: [run_row(1)], recaps: [recap_row(1), recap_row(2)])
  reaches_generator = false
  result = capture(name, now: NOW, tables: TABLES, seed: { community_chat_recap_runs: runs, community_chat_recaps: recaps }, sidekiq: true, job: "GenerateCommunityChatRecapJob", args:) do
    GenerateCommunityChatRecapJob.new.perform(*args)
  rescue HandBackMarker
    reaches_generator = true
  end
  result.delete("seed")
  result.merge("reaches_generator" => reaches_generator)
end

def exhausted(name, args, job_class: "GenerateCommunityChatRecapJob", runs: [run_row(1)], recaps: [recap_row(1), recap_row(2)], message: "boom")
  job = { "class" => job_class, "args" => args }
  result = capture(name, now: NOW, tables: TABLES, seed: { community_chat_recap_runs: runs, community_chat_recaps: recaps }, sidekiq: true, job: "GenerateCommunityChatRecapJob", args:, hook: true, job_class:) do
    GenerateCommunityChatRecapJob.sidekiq_retries_exhausted_block.call(job, StandardError.new(message))
  end
  result.delete("seed")
  result.merge("message" => message)
end

cases = []
cases << run("a recap that does not exist", [9])
cases << run("a recap id of nil", [nil])
cases << run("a recap id as a digit string", ["1"])
cases << run("a recap id as a float", [1.0])
cases << run("a recap id as a word", ["one"])
cases << run("a recap", [1])
cases << run("a recap among others", [2], recaps: [recap_row(1), recap_row(2), recap_row(3)])
cases << run("no arguments", [])
cases << run("two arguments", [1, 2])

cases << exhausted("exhausted with a second recap still pending", [1])
cases << exhausted("exhausted with the other recap finished", [1], recaps: [recap_row(1), recap_row(2, status: "finished")])
cases << exhausted("exhausted with the other recap failed", [1], recaps: [recap_row(1), recap_row(2, status: "failed")])
cases << exhausted("exhausted with the other recap not created yet", [1], recaps: [recap_row(1)])
cases << exhausted("exhausted with more recaps than the run counts", [1], recaps: [recap_row(1), recap_row(2, status: "finished"), recap_row(3, status: "finished")])
cases << exhausted("exhausted with a pending recap beyond the run's count", [1], runs: [run_row(1, recaps_count: 1)], recaps: [recap_row(1), recap_row(2)])
cases << exhausted("exhausted with a run that counts no recaps", [1], runs: [run_row(1, recaps_count: 0)], recaps: [recap_row(1, status: "finished")])
cases << exhausted("exhausted with a run that already finished", [1], runs: [run_row(1, finished_at: SEEDED_AT, notified_at: SEEDED_AT)], recaps: [recap_row(1), recap_row(2, status: "finished")])
cases << exhausted("exhausted for the last recap of a daily run on a Saturday", [1], runs: [run_row(1, from: "2026-11-07 00:00:00")], recaps: [recap_row(1), recap_row(2, status: "finished")])
cases << exhausted("exhausted for the last recap of a weekly run", [1], runs: [run_row(1, frequency: "weekly", from: "2026-11-07 00:00:00")], recaps: [recap_row(1), recap_row(2, status: "finished")])
cases << exhausted("exhausted with an already failed recap", [1], recaps: [recap_row(1, status: "failed", error_message: "old"), recap_row(2, status: "finished")])
cases << exhausted("exhausted with an already finished recap", [1], recaps: [recap_row(1, status: "finished"), recap_row(2, status: "finished")])
cases << exhausted("exhausted among other runs", [3], runs: [run_row(1), run_row(2, from: "2026-11-02 00:00:00")], recaps: [recap_row(1), recap_row(2), recap_row(3, run: 2), recap_row(4, run: 2, status: "finished")])
cases << exhausted("exhausted with a long message", [1], message: "x" * 300)
cases << exhausted("exhausted with a message of 255 characters", [1], message: "y" * 255)
cases << exhausted("exhausted with a multibyte message", [1], message: "failed: é ✓")
cases << exhausted("exhausted with an empty message", [1], message: "")
cases << exhausted("exhausted with a message with quotes", [1], message: "it's \"bad\"\nreally")
cases << exhausted("exhausted for a recap that does not exist", [9])
cases << exhausted("exhausted with no arguments", [])
cases << exhausted("exhausted with an id of nil", [nil])
cases << exhausted("exhausted with an empty string id", [""])
cases << exhausted("exhausted with a digit string id", ["1"])
cases << exhausted("exhausted with a float id", [1.0])
cases << exhausted("exhausted with a word id", ["one"])
cases << exhausted("exhausted with the id 0", [0])
cases << exhausted("exhausted for another job class", [1], job_class: "Other")

File.write(OUT, JSON.pretty_generate({ "now" => NOW.to_f, "cases" => cases }) + "\n")
puts "wrote #{OUT.relative_path_from(Rails.root)} (#{cases.size} cases)"
